import{_ as t,o as a,c as o,a0 as l}from"./chunks/framework.CI7OaYtj.js";const g=JSON.parse('{"title":"uni 插件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/uni-plugin.md","filePath":"guide/uni-plugin.md"}'),d={name:"guide/uni-plugin.md"};function i(s,e,n,c,r,u){return a(),o("div",null,[...e[0]||(e[0]=[l(`<h1 id="uni-插件" tabindex="-1">uni 插件 <a class="header-anchor" href="#uni-插件" aria-label="Permalink to &quot;uni 插件&quot;">​</a></h1><p>项目通过 <code>uni_modules/</code> 管理跨端插件。业务代码只从插件<strong>公开入口</strong>导入，不要穿透到 <code>core/</code>、<code>hooks/</code> 等内部目录。</p><h2 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">模块</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/unibestX/docs/guide/route.html"><code>route-bestX</code></a></td><td style="text-align:left;">路由引擎、<code>useRoute</code> / <code>useRouter</code>、全局守卫与页面快照</td></tr><tr><td style="text-align:left;"><a href="/unibestX/docs/guide/request.html"><code>request-bestX</code></a></td><td style="text-align:left;">请求实例、拦截器、缓存、<code>useQuery</code> / <code>useMutation</code>、流式请求</td></tr><tr><td style="text-align:left;"><code>x-pinia-s</code></td><td style="text-align:left;">App VDOM 模式下的 Pinia 适配</td></tr><tr><td style="text-align:left;"><code>z-paging-x</code></td><td style="text-align:left;">原生分页列表与下拉刷新</td></tr><tr><td style="text-align:left;"><code>lime-i18n</code></td><td style="text-align:left;">多语言运行时</td></tr><tr><td style="text-align:left;"><code>lime-icon</code></td><td style="text-align:left;">Iconify / 字体 / SVG 图标集合</td></tr><tr><td style="text-align:left;"><code>uni-icons</code></td><td style="text-align:left;">轻量字体图标组件</td></tr><tr><td style="text-align:left;"><code>lime-shared</code> / <code>lime-use</code> / <code>lime-color</code></td><td style="text-align:left;">通用工具、组合式 hooks 与颜色能力</td></tr></tbody></table><h2 id="使用原则" tabindex="-1">使用原则 <a class="header-anchor" href="#使用原则" aria-label="Permalink to &quot;使用原则&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✅ 从公开入口导入</span></span>
<span class="line"><span>import { useRoute, useRouter } from &#39;@/uni_modules/route-bestX/index.uts&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// ❌ 不要穿透内部实现</span></span>
<span class="line"><span>import { useRoute } from &#39;@/uni_modules/route-bestX/core/route.uts&#39;;</span></span></code></pre></div><ul><li>公共能力优先复用现有模块，不在页面里重复造轮子。</li><li>插件模块内部必须保持单向依赖，禁止循环依赖。</li><li>Easycom 范围内的组件直接写短横线标签，不需要手动 import。</li><li>页面私有组件必须手动 import。</li><li>修改生态插件前先确认 Vapor / VDOM 与目标平台兼容性。</li></ul><h2 id="页面配置插件" tabindex="-1">页面配置插件 <a class="header-anchor" href="#页面配置插件" aria-label="Permalink to &quot;页面配置插件&quot;">​</a></h2><p>项目还内置了 Vite 插件：</p><ul><li><code>vite-plugin-uni-pages</code>：扫描页面并生成 <code>pages.json</code>。</li><li><code>uni-layouts-plugin</code>：把页面包进 <code>default</code> / <code>empty</code> / <code>navbar</code> 布局。</li><li><code>tabbarViewsPlugin</code>：根据 TabBar 配置生成单页容器。</li><li><code>root-plugin</code>：自动挂载全局根骨架。</li></ul><p><code>pages.json</code> 是生成物，页面配置请写在 <code>definePage</code> 或 <code>pages.config.json</code> 中。详见<a href="/unibestX/docs/guide/uni-pages.html">文件路由与页面配置</a>。</p>`,11)])])}const h=t(d,[["render",i]]);export{g as __pageData,h as default};
